/* DESIGN D28 section 9: the console's widths, one function for the kernel (kernel/confont.c) and the programs
 * (user/libz.c's zu8width), so the console and Zenix's own programs agree on every column. picolibc's wcwidth in its
 * non-CJK locale, from the same two tables the C library is compiled from (conwidth.h, generated by
 * tools/mkconfont.py widths): 0 for NUL and the zero-width ranges, 2 for the wide ranges, -1 for the other controls,
 * U+007F-009F, the surrogates and what is not a character, 1 for everything else. */
#ifndef ZENIX_CWIDTH_H
#define ZENIX_CWIDTH_H
#include "conwidth.h"

static int cw_in16(unsigned int c, const unsigned short (*r)[2], int n)
{
    int lo = 0, hi = n - 1;
    if (n <= 0 || c < r[0][0] || c > r[n - 1][1])
        return 0;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (c > r[mid][1])
            lo = mid + 1;
        else if (c < r[mid][0])
            hi = mid - 1;
        else
            return 1;
    }
    return 0;
}

#define CW_NR(a) ((int)(sizeof(a) / sizeof((a)[0])))

static int cw_width(unsigned int c)
{
    if (c == 0)
        return 0;
    if (c - 0x20u < 0x5Fu)
        return 1;
    if (c < 0xA0 || (c >= 0xD800 && c <= 0xDFFF) || c > 0x10FFFF)
        return -1;
    if (c < 0x300)
        return 1;                       /* below the first zero-width range every printable character is 1 */
    if (c <= 0xFFFF)
        return cw_in16(c, cw_zero16, CW_NR(cw_zero16)) ? 0 : cw_in16(c, cw_wide16, CW_NR(cw_wide16)) ? 2 : 1;
    unsigned int p = c >> 16, l = c & 0xFFFF;           /* above U+FFFF: the plane's own ranges, 16 bits */
    return cw_in16(l, cw_zeroA + cw_zerop[p], cw_zerop[p + 1] - cw_zerop[p]) ? 0 :
           cw_in16(l, cw_wideA + cw_widep[p], cw_widep[p + 1] - cw_widep[p]) ? 2 : 1;
}
#endif
